def is_valid_card_number(card_number: str) -> bool:
    """Buggy: incorrect inclusive/exclusive handling for length boundaries."""
    if not isinstance(card_number, str):
        return False

    if not card_number.isdigit():
        return False

    # BUG: should allow 13..19 inclusive, but this excludes exactly 13 and 19.
    n = len(card_number)
    if n <= 13 or n >= 19:
        return False

    total = 0
    double = False
    for ch in reversed(card_number):
        d = ord(ch) - ord('0')
        if double:
            d *= 2
            if d > 9:
                d -= 9
        total += d
        double = not double

    return total % 10 == 0

